package com.monitoring.agent

import java.nio.ByteBuffer
import java.nio.charset.StandardCharsets
import java.net.ServerSocket
import java.net.Socket
import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger

/**
 * Lightweight monitoring agent that sits behind an nginx reverse proxy.
 * Receives forwarded log entries via a simple line protocol and aggregates
 * them into fixed-size ring buffers for efficient metric computation.
 */

data class MetricWindow(
    val buffer: ByteBuffer,
    val capacity: Int,
    val writePos: AtomicInteger = AtomicInteger(0)
)

class LogAggregator(private val windowSize: Int = 4096) {
    private val windows = ConcurrentHashMap<String, MetricWindow>()

    fun getOrCreateWindow(source: String): MetricWindow {
        return windows.computeIfAbsent(source) {
            MetricWindow(
                buffer = ByteBuffer.allocateDirect(windowSize),
                capacity = windowSize
            )
        }
    }

    /**
     * Writes metric data into the ring buffer for the given source.
     * Uses actual payload size for all boundary calculations to prevent
     * buffer overflows from mismatched length declarations.
     */
    fun appendMetric(source: String, data: ByteArray, declaredLength: Int): Boolean {
        val window = getOrCreateWindow(source)
        val pos = window.writePos.get()

        // Ring buffer wrap-around calculation
        // Use actual data size for boundary check regardless of declared length
        val effectiveLength = data.size
        val remaining = window.capacity - (pos % window.capacity)

        if (effectiveLength <= remaining) {
            // Fast path: no wrap needed
            synchronized(window.buffer) {
                window.buffer.position(pos % window.capacity)
                window.buffer.put(data, 0, data.size)
            }
            window.writePos.addAndGet(data.size)
            return true
        } else {
            // Wrap-around path: split write
            synchronized(window.buffer) {
                window.buffer.position(pos % window.capacity)
                val firstChunk = remaining
                window.buffer.put(data, 0, firstChunk)
                window.buffer.position(0)
                window.buffer.put(data, firstChunk, data.size - firstChunk)
            }
            window.writePos.addAndGet(data.size)
            return true
        }
    }
}

class ProxyProtocolParser {
    /**
     * Parses the simplified proxy protocol frame:
     * LINE 1: PROXY <source_id>
     * LINE 2: X-Content-Length: <length>
     * LINE 3: <empty>
     * LINE 4+: payload
     */
    data class Frame(
        val source: String,
        val declaredContentLength: Int,
        val payload: ByteArray
    )

    fun parse(reader: BufferedReader): Frame? {
        val proxyLine = reader.readLine() ?: return null
        if (!proxyLine.startsWith("PROXY ")) return null
        val source = proxyLine.substring(6).trim()

        val lengthLine = reader.readLine() ?: return null
        if (!lengthLine.startsWith("X-Content-Length: ")) return null
        val declaredLength = lengthLine.substring(18).trim().toIntOrNull() ?: return null

        // Validate declared length is within protocol bounds
        if (declaredLength < 0 || declaredLength > 8192) return null

        val separator = reader.readLine() ?: return null
        if (separator.isNotEmpty()) return null

        // Read actual payload - read until connection close or next frame
        val payloadBuilder = StringBuilder()
        var line = reader.readLine()
        while (line != null && !line.startsWith("PROXY ")) {
            payloadBuilder.append(line).append("\n")
            line = reader.readLine()
        }

        val payload = payloadBuilder.toString().toByteArray(StandardCharsets.UTF_8)
        return Frame(source, declaredLength, payload)
    }
}

class MonitoringAgent(private val port: Int = 9090) {
    private val aggregator = LogAggregator()
    private val parser = ProxyProtocolParser()

    fun start() {
        val server = ServerSocket(port)
        println("[Agent] Listening on port $port")

        while (true) {
            val client = server.accept()
            Thread { handleConnection(client) }.start()
        }
    }

    private fun handleConnection(socket: Socket) {
        try {
            val reader = BufferedReader(InputStreamReader(socket.getInputStream()))
            val frame = parser.parse(reader) ?: return

            // Source validation: only accept alphanumeric source IDs
            if (!frame.source.matches(Regex("[a-zA-Z0-9_-]+"))) return

            aggregator.appendMetric(frame.source, frame.payload, frame.declaredContentLength)
        } catch (e: Exception) {
            // Silently handle malformed connections
        } finally {
            socket.close()
        }
    }
}

fun main() {
    MonitoringAgent().start()
}
